  const instructor=await store.createAccount(admin.id,{person_id:x.f.mentor,login:'twi-instructor',password:password(),generate:false});
  await store.setPolicy(admin.id,{role_id:instructorRole,revision:0,permissions:['training.read','training.detail','training.stage','person.read_basic']});
  await store.grant(admin.id,{account_id:instructor.id,assignment_id:instructorAssignment,scope:{kind:'assigned'},valid_to:null});
  const headRole=(await store.createReference(admin.id,'business_role',{code:'TWI-PLAN-HEAD',name:'Руководитель согласования плана'})).id;
  const headAssignment=(await store.createReference(admin.id,'role_assignment',{person_id:x.f.other,role_id:headRole,valid_from:'2020-01-01',valid_to:null})).id;
  const head=await store.createAccount(admin.id,{person_id:x.f.other,login:'twi-head',password:password(),generate:false});
  await store.setPolicy(admin.id,{role_id:headRole,revision:0,permissions:['training.read','training.detail','training.approve_head']});
  const localGrant=await store.grant(admin.id,{account_id:head.id,assignment_id:headAssignment,scope:{kind:'unit_tree',unit_id:x.f.unit},valid_to:null});
  const workerPass=password(),worker=await store.createAccount(admin.id,{person_id:x.f.trainee,login:'twi-worker',password:workerPass,generate:false});
  await store.setPolicy(admin.id,{role_id:x.workerRole,revision:0,permissions:['person.read_basic','person.read_card','training.read','training.detail','assessment.read','assessment.detail']});
  await store.grant(admin.id,{account_id:worker.id,assignment_id:x.workerAssignment,scope:{kind:'self'},valid_to:null});
  const create={operation_id:x.f.operation,trainee_id:x.f.trainee,authorization_id:x.f.auth,revision_id:x.revision.revision,skill_id:x.f.skill,scale_id:x.matrixScale,target_level:2,assigned_on:day,due_on:due,reason:'Учебный производственный план',variant:'classic',method_config:{followups:2,segments:[],realShow:null,realTry:null,hazardous:false},plan_reviewed:true,scenario:'development'};
