  await assert.rejects(store.createTraining(manager.id,1,{...create,rapid_confirm:true}),/Оперативное согласование/);
  const first=await store.createTraining(manager.id,1,create),second=await store.createTraining(manager.id,1,{...create,trainee_id:x.personB,scenario:'rapid'});
